import sys, types
# Hermetic fallback if sqlalchemy is not in host interpreter
if 'sqlalchemy' not in sys.modules:
    m = types.ModuleType('sqlalchemy')
    m.text = lambda s: {'_sql_text_clause': s}
    sys.modules['sqlalchemy'] = m

from repository import get_user_query

class MockSession:
    def execute(self, stmt, params=None):
        if isinstance(stmt, str):
            raise ValueError("ArgumentError: Textual SQL expression must be explicitly declared as text()")
        return "OK"

try:
    get_user_query(MockSession(), 42)
    sys.exit(0)
except ValueError as e:
    if "ArgumentError: Textual SQL expression" in str(e):
        sys.stderr.write(str(e) + "\n")
        sys.exit(1)
    sys.exit(2)

